class Solution {
public:
    int maximumRequests(int n, vector<vector<int>>& requests) {
        int m = requests.size();
        int ans = 0;
        vector<int> balance(n);
        for (int mask = 0; mask < (1 << m); ++mask) {
            fill(balance.begin(), balance.end(), 0);
            for (int i = 0; i < m; ++i) {
                if (mask & (1 << i)) {
                    int from = requests[i][0];
                    int to   = requests[i][1];
                    --balance[from];
                    ++balance[to];
                }
            }
            bool ok = true;
            for (int v : balance) {
                if (v != 0) { ok = false; break; }
            }
            if (ok) {
                int cnt = __builtin_popcount(mask);
                ans = max(ans, cnt);
            }
        }
        return ans;
    }
};
